<!DOCTYPE html>
<html lang="ar" dir="rtl">

<head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>تصميم البطاقة الجامعية - جامعة العلوم الصحية</title>
    <script src="https://cdn.tailwindcss.com/3.4.17"></script>
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;800;900&family=Tajawal:wght@400;500;700;800&family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
    <style>
        :root {
            --card-w: 548px;
            --card-h: 392px;
        }

        * {
            box-sizing: border-box;
        }

        body {
            font-family: 'Cairo', 'Tajawal', 'Inter', sans-serif;
            background-color: #0f172a;
            color: #f8fafc;
            margin: 0;
            padding: 0;
            overflow-x: hidden;
        }

        /* Textured stone showcase backdrop matching original image */
        .stone-backdrop {
            background-color: #c8c6c1;
            background-image:
                radial-gradient(circle at 20% 25%, rgba(255, 255, 255, 0.35) 0%, transparent 45%),
                radial-gradient(circle at 80% 75%, rgba(0, 0, 0, 0.14) 0%, transparent 50%),
                repeating-linear-gradient(45deg, rgba(255, 255, 255, 0.03) 0px, rgba(255, 255, 255, 0.03) 2px, rgba(0, 0, 0, 0.03) 2px, rgba(0, 0, 0, 0.03) 4px),
                linear-gradient(135deg, #d5d3ce 0%, #bfbdb7 50%, #AEACA6 100%);
            box-shadow: inset 0 2px 20px rgba(0, 0, 0, 0.18);
        }

        .dark-backdrop {
            background: radial-gradient(circle at center, #1e293b 0%, #0f172a 100%);
        }

        .light-backdrop {
            background: linear-gradient(135deg, #f8fafc 0%, #e2e8f0 100%);
        }

        /* ID Card Base Container */
        .id-card {
            width: var(--card-w);
            height: var(--card-h);
            position: relative;
            border-radius: 20px;
            overflow: hidden;
            background: linear-gradient(145deg, #f3f2ee 0%, #e9e8e3 55%, #e2e0da 100%);
            box-shadow:
                -12px 18px 28px rgba(0, 0, 0, 0.32),
                0 4px 10px rgba(0, 0, 0, 0.16),
                inset 0 1px 1px rgba(255, 255, 255, 0.8);
            user-select: none;
            flex-shrink: 0;
            direction: rtl;
        }

        /* Responsive scaling wrapper for smaller viewports */
        .card-scale-wrapper {
            display: flex;
            justify-content: center;
            align-items: center;
            transform-origin: center center;
            transition: transform 0.25s ease;
        }

        /* 3D Flip Mode Styles */
        .perspective-stage {
            perspective: 1600px;
        }

        .flip-container {
            width: var(--card-w);
            height: var(--card-h);
            position: relative;
            transform-style: preserve-3d;
            transition: transform 0.75s cubic-bezier(0.4, 0.2, 0.2, 1);
            cursor: pointer;
        }

        .flip-container.is-flipped {
            transform: rotateY(180deg);
        }

        .flip-face {
            position: absolute;
            inset: 0;
            backface-visibility: hidden;
            -webkit-backface-visibility: hidden;
        }

        .flip-back {
            transform: rotateY(180deg);
        }

        /* Employee Photo Frame */
        .photo-frame {
            position: absolute;
            left: 38px;
            top: 56px;
            width: 147px;
            height: 206px;
            border-radius: 16px;
            border: 3.5px solid #d4d7dd;
            box-shadow: 0 6px 16px rgba(0, 0, 0, 0.35), inset 0 0 0 1px rgba(255, 255, 255, 0.4);
            overflow: hidden;
            background: #b8b6b2;
            z-index: 10;
        }

        /* Signature Styling Filters */
        .sig-tint-silver {
            filter: drop-shadow(0 1px 2px rgba(0, 0, 0, 0.45)) brightness(1.05);
        }

        .sig-tint-gold {
            filter: sepia(1) saturate(3.8) hue-rotate(5deg) brightness(1.02) drop-shadow(0 1px 2px rgba(0, 0, 0, 0.5));
        }

        .sig-tint-cyan {
            filter: sepia(1) saturate(3) hue-rotate(165deg) brightness(1.1) drop-shadow(0 1px 2px rgba(0, 0, 0, 0.45));
        }

        .sig-tint-dark {
            filter: drop-shadow(0 0 3px rgba(255, 255, 255, 0.75));
        }

        /* Custom Scrollbar */
        ::-webkit-scrollbar {
            width: 6px;
            height: 6px;
        }

        ::-webkit-scrollbar-track {
            background: #0f172a;
        }

        ::-webkit-scrollbar-thumb {
            background: #334155;
            border-radius: 9999px;
        }

        /* ===== نظام الطباعة المتعدد - A4 Landscape ===== */
        @media print {
            /* إخفاء كل شيء افتراضيًا عند الطباعة */
            body > * {
                display: none !important;
            }

            /* إظهار طبقة الطباعة فقط */
            #printOverlay {
                display: block !important;
            }

            @page {
                size: A4 landscape;
                margin: 8mm;
            }

            #printOverlay {
                position: fixed !important;
                top: 0 !important;
                left: 0 !important;
                width: 100% !important;
                height: 100% !important;
                background: white !important;
            }

            .print-page {
                width: 281mm;
                min-height: 190mm;
                display: grid;
                grid-template-columns: 1fr 1fr;
                grid-template-rows: auto;
                gap: 4mm;
                padding: 0;
                margin: 0;
                page-break-after: always;
                page-break-inside: avoid;
                align-content: start;
            }

            .print-page:last-child {
                page-break-after: auto;
            }

            .print-card-slot {
                width: 100%;
                overflow: hidden;
                display: flex;
                align-items: center;
                justify-content: center;
            }

            /* تصغير البطاقة لتلائم A4 */
            .print-card-slot .id-card {
                transform: scale(0.882);
                transform-origin: top left;
                box-shadow: none !important;
                border: 0.5px solid #cbd5e1 !important;
                flex-shrink: 0;
            }

            .print-card-slot-wrapper {
                width: 483px; /* 548 * 0.882 ≈ 483 */
                height: 346px; /* 392 * 0.882 ≈ 346 */
                overflow: hidden;
                display: block;
            }
        }

        /* ===== Modal الطباعة (شاشة الاختيار) ===== */
        #printModal {
            display: none;
            position: fixed;
            inset: 0;
            z-index: 1000;
            background: rgba(0,0,0,0.75);
            backdrop-filter: blur(4px);
            overflow-y: auto;
            padding: 20px;
        }

        #printModal.active {
            display: flex;
            align-items: flex-start;
            justify-content: center;
        }

        #printModalInner {
            background: #1e293b;
            border: 1px solid #334155;
            border-radius: 20px;
            width: 100%;
            max-width: 820px;
            padding: 28px;
            box-shadow: 0 25px 60px rgba(0,0,0,0.6);
            margin: auto;
        }

        .print-card-count-btn {
            padding: 10px 20px;
            border-radius: 12px;
            border: 2px solid #334155;
            background: #0f172a;
            color: #94a3b8;
            font-weight: 700;
            font-size: 14px;
            cursor: pointer;
            transition: all 0.2s;
        }

        .print-card-count-btn.active {
            border-color: #3b82f6;
            background: rgba(59,130,246,0.15);
            color: #60a5fa;
        }

        .print-card-count-btn:hover {
            border-color: #60a5fa;
            color: #fff;
        }

        .print-data-card {
            background: #0f172a;
            border: 1px solid #334155;
            border-radius: 14px;
            padding: 14px 16px;
            margin-bottom: 12px;
        }

        .print-data-card h4 {
            color: #60a5fa;
            font-weight: 700;
            font-size: 13px;
            margin-bottom: 10px;
            padding-bottom: 6px;
            border-bottom: 1px solid #1e293b;
        }

        .print-data-card input[type="text"] {
            width: 100%;
            background: #1e293b;
            border: 1px solid #334155;
            border-radius: 8px;
            color: white;
            font-size: 12px;
            padding: 6px 10px;
            outline: none;
            box-sizing: border-box;
        }

        .print-data-card input[type="text"]:focus {
            border-color: #3b82f6;
        }

        .print-data-card label {
            font-size: 11px;
            color: #94a3b8;
            font-weight: 600;
            display: block;
            margin-bottom: 3px;
            margin-top: 7px;
        }

        .print-data-card label:first-of-type {
            margin-top: 0;
        }

        /* A4 معاينة صغيرة */
        .print-a4-preview {
            background: white;
            border: 2px solid #334155;
            border-radius: 8px;
            aspect-ratio: 297/210;
            display: grid;
            grid-template-columns: 1fr 1fr;
            grid-template-rows: 1fr 1fr;
            gap: 4px;
            padding: 6px;
            width: 240px;
            flex-shrink: 0;
        }

        .print-a4-slot {
            border-radius: 4px;
            border: 1.5px dashed #94a3b8;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 9px;
            color: #64748b;
            font-weight: 600;
        }

        .print-a4-slot.filled {
            background: rgba(59,130,246,0.15);
            border-color: #3b82f6;
            color: #3b82f6;
        }

        /* طبقة الطباعة الفعلية */
        #printOverlay {
            display: none;
            position: fixed;
            top: 0; left: 0;
            width: 100%; height: 100%;
            background: white;
            z-index: 9999;
            padding: 0;
            overflow: hidden;
        }
    </style>
</head>

<body class="min-h-screen flex flex-col bg-slate-950 text-slate-100">

    <!-- Top Navigation & Action Bar -->
    <header class="no-print sticky top-0 z-30 bg-slate-900/95 backdrop-blur border-b border-slate-800 px-4 py-3">
        <div class="max-w-7xl mx-auto flex flex-wrap items-center justify-between gap-3">
            <!-- Brand / Title -->
            <div class="flex items-center gap-3">
                <div class="w-10 h-10 rounded-xl bg-blue-600/20 border border-blue-500/40 flex items-center justify-center text-blue-400 font-bold text-lg">
                    🪪
                </div>
                <div>
                    <h1 class="text-base sm:text-lg font-bold text-white leading-tight">استوديو البطاقة الجامعية الذكية — جامعة العلوم الصحية</h1>
                    <p class="text-xs text-slate-400">تم تحديث التوقيع الإداري وتحويل كامل التصميم الأمامي والخلفي إلى ملف ويب تفاعلي قابل للتعديل والطباعة</p>
                </div>
            </div>

            <!-- View Switcher Pills -->
            <div class="flex items-center bg-slate-800/90 p-1 rounded-xl border border-slate-700/80 text-xs sm:text-sm">
                <button id="btnViewBoth" type="button" class="px-3 py-1.5 rounded-lg font-semibold bg-blue-600 text-white shadow transition">
                    الوجهان معاً
                </button>
                <button id="btnViewFlip" type="button" class="px-3 py-1.5 rounded-lg font-semibold text-slate-300 hover:text-white transition">
                    عرض 3D قابل للقلب
                </button>
                <button id="btnViewFront" type="button" class="px-3 py-1.5 rounded-lg font-semibold text-slate-300 hover:text-white transition">
                    الأمامي فقط
                </button>
                <button id="btnViewBack" type="button" class="px-3 py-1.5 rounded-lg font-semibold text-slate-300 hover:text-white transition">
                    الخلفي فقط
                </button>
            </div>

            <!-- Export & Editor Actions -->
            <div class="flex items-center gap-2">
                <button id="btnToggleEditor" type="button" class="px-3.5 py-2 rounded-xl bg-slate-800 hover:bg-slate-700 border border-slate-700 text-xs sm:text-sm font-semibold text-slate-200 flex items-center gap-1.5 transition">
                    <span>⚙️</span>
                    <span id="editorToggleLabel">إخفاء لوحة التحكم</span>
                </button>
                <button id="btnDownloadPng" type="button" class="px-3.5 py-2 rounded-xl bg-emerald-600 hover:bg-emerald-500 text-xs sm:text-sm font-bold text-white shadow-lg shadow-emerald-900/30 flex items-center gap-1.5 transition">
                    <span>📥</span>
                    <span>حفظ كصورة PNG</span>
                </button>
                <button id="btnPrintCard" type="button" class="px-3.5 py-2 rounded-xl bg-blue-600 hover:bg-blue-500 text-xs sm:text-sm font-bold text-white shadow-lg shadow-blue-900/30 flex items-center gap-1.5 transition">
                    <span>🖨️</span>
                    <span>طباعة A4</span>
                </button>
            </div>
        </div>
    </header>

    <!-- Main Workspace -->
    <main class="flex-1 flex flex-col lg:flex-row overflow-hidden">

        <!-- Card Preview Stage -->
        <section id="previewStage" class="stone-backdrop flex-1 flex flex-col items-center justify-center p-4 sm:p-8 lg:p-10 relative overflow-auto min-h-[480px] transition-colors duration-300">

            <!-- Top Floating Stage Controls -->
            <div class="no-print mb-5 flex flex-wrap items-center justify-center gap-2 bg-slate-900/80 backdrop-blur-md px-4 py-2 rounded-full border border-white/10 text-xs shadow-lg">
                <span class="text-slate-300 font-medium ml-1">خلفية العرض:</span>
                <button type="button" data-bg="stone" class="bg-preset-btn px-2.5 py-1 rounded-full bg-blue-600 text-white font-semibold transition">رخامي (الأصلي)</button>
                <button type="button" data-bg="dark" class="bg-preset-btn px-2.5 py-1 rounded-full bg-slate-800 text-slate-300 hover:text-white transition">داكن</button>
                <button type="button" data-bg="light" class="bg-preset-btn px-2.5 py-1 rounded-full bg-slate-800 text-slate-300 hover:text-white transition">فاتح</button>
                <span class="mx-1 text-slate-600">|</span>
                <span class="text-slate-300 font-medium">التكبير:</span>
                <input id="zoomRange" type="range" min="60" max="125" value="100" class="w-24 accent-blue-500 cursor-pointer" />
                <span id="zoomValueLabel" class="text-slate-200 font-mono w-10 text-left">100%</span>
            </div>

            <!-- Flip Hint Banner (Only visible in 3D Flip mode) -->
            <div id="flipHintBar" class="no-print hidden mb-4">
                <button id="btnFlipAction" type="button" class="px-4 py-2 rounded-full bg-blue-600 hover:bg-blue-500 text-white font-bold text-xs sm:text-sm shadow-lg flex items-center gap-2 transition">
                    <span>🔄</span>
                    <span>اضغط هنا أو على البطاقة لقلبها بين الوجه الأمامي والخلفي</span>
                </button>
            </div>

            <!-- Cards Container -->
            <div id="cardsScaleContainer" class="card-scale-wrapper">
                <div id="cardsLayoutBox" class="flex flex-col xl:flex-row items-center justify-center gap-8">

                    <!-- ================= FRONT CARD (الوجه الأمامي) ================= -->
                    <div id="frontCardWrapper" class="flex flex-col items-center">
                        <div id="frontCard" class="id-card">

                            <!-- Background SVG Artwork: Light Blue Waves + Left Dark Blue Curved Panel + Guilloche Pattern -->
                            <svg class="absolute inset-0 w-full h-full pointer-events-none" viewBox="0 0 548 392" xmlns="http://www.w3.org/2000/svg">
                                <defs>
                                    <!-- Dark Navy Gradient for Left Panel -->
                                    <linearGradient id="navyPanelGrad" x1="0%" y1="0%" x2="100%" y2="100%">
                                        <stop offset="0%" stop-color="#153268" />
                                        <stop offset="50%" stop-color="#1b3b75" />
                                        <stop offset="100%" stop-color="#102754" />
                                    </linearGradient>

                                    <!-- Translucent Medium Blue Rim Gradient -->
                                    <linearGradient id="rimBlueGrad" x1="0%" y1="0%" x2="0%" y2="100%">
                                        <stop offset="0%" stop-color="#799bc2" stop-opacity="0.65" />
                                        <stop offset="50%" stop-color="#4e74a3" stop-opacity="0.75" />
                                        <stop offset="100%" stop-color="#6c8fb8" stop-opacity="0.65" />
                                    </linearGradient>

                                    <!-- Clip Path for Front Left Navy Panel -->
                                    <clipPath id="frontNavyClip">
                                        <path d="M 0,0 L 210,0 C 232,38 242,96 292,123 C 235,134 205,172 212,232 C 219,290 226,342 188,392 L 0,392 Z" />
                                    </clipPath>

                                    <!-- Intricate Spirograph / Guilloche Pattern for Navy Panel -->
                                    <pattern id="guillochePattern" x="0" y="0" width="140" height="140" patternUnits="userSpaceOnUse">
                                        <g fill="none" stroke="#3b82f6" stroke-width="0.55" stroke-opacity="0.32">
                                            <circle cx="70" cy="70" r="64" />
                                            <circle cx="70" cy="70" r="52" />
                                            <circle cx="70" cy="70" r="40" />
                                            <circle cx="70" cy="70" r="28" />
                                            <ellipse cx="70" cy="70" rx="66" ry="22" transform="rotate(0 70 70)" />
                                            <ellipse cx="70" cy="70" rx="66" ry="22" transform="rotate(30 70 70)" />
                                            <ellipse cx="70" cy="70" rx="66" ry="22" transform="rotate(60 70 70)" />
                                            <ellipse cx="70" cy="70" rx="66" ry="22" transform="rotate(90 70 70)" />
                                            <ellipse cx="70" cy="70" rx="66" ry="22" transform="rotate(120 70 70)" />
                                            <ellipse cx="70" cy="70" rx="66" ry="22" transform="rotate(150 70 70)" />
                                            <path d="M 0,35 Q 35,0 70,35 T 140,35" stroke="#60a5fa" stroke-opacity="0.28" />
                                            <path d="M 0,70 Q 35,35 70,70 T 140,70" stroke="#60a5fa" stroke-opacity="0.28" />
                                            <path d="M 0,105 Q 35,70 70,105 T 140,105" stroke="#60a5fa" stroke-opacity="0.28" />
                                        </g>
                                    </pattern>
                                </defs>

                                <!-- Subtle Right-Side Sky Blue Flowing Wave Lines (Background) -->
                                <g fill="none" stroke="#8fb3d9" stroke-width="0.8" opacity="0.45">
                                    <path d="M 225,0 C 265,65 390,45 480,0" />
                                    <path d="M 232,0 C 272,72 396,52 492,0" />
                                    <path d="M 240,0 C 280,80 404,60 504,0" />
                                    <path d="M 248,0 C 288,88 412,68 516,0" />
                                    <path d="M 256,0 C 296,96 420,76 528,0" />
                                    <path d="M 264,0 C 304,104 428,84 540,0" />
                                    <path d="M 272,0 C 312,112 436,92 548,5" />
                                    <path d="M 280,0 C 320,120 444,100 548,15" />

                                    <!-- Lower Flowing Waves from Center-Right to Bottom-Left -->
                                    <path d="M 548,210 C 440,220 355,310 195,365" />
                                    <path d="M 548,220 C 442,230 358,318 195,372" />
                                    <path d="M 548,230 C 444,240 362,326 195,379" />
                                    <path d="M 548,240 C 446,250 366,334 195,386" />
                                    <path d="M 548,250 C 448,260 370,342 195,392" />
                                    <path d="M 548,260 C 450,270 374,350 210,392" />
                                    <path d="M 548,270 C 452,280 378,358 225,392" />
                                    <path d="M 548,280 C 454,290 382,366 240,392" />
                                </g>

                                <!-- Faint 4-Point Star Sparkles -->
                                <g fill="#9ab8d9" opacity="0.55">
                                    <path d="M 358,328 L 361,335 L 368,338 L 361,341 L 358,348 L 355,341 L 348,338 L 355,335 Z" />
                                    <path d="M 382,110 L 384,115 L 389,117 L 384,119 L 382,124 L 380,119 L 375,117 L 380,115 Z" />
                                </g>

                                <!-- Outer Medium-Blue Rim Along Curve -->
                                <path d="M 0,0 L 222,0 C 244,40 255,96 312,123 C 248,134 217,172 224,232 C 231,290 238,342 200,392 L 0,392 Z" fill="url(#rimBlueGrad)" />

                                <!-- Main Left Dark Navy Curved Panel -->
                                <path d="M 0,0 L 210,0 C 232,38 242,96 292,123 C 235,134 205,172 212,232 C 219,290 226,342 188,392 L 0,392 Z" fill="url(#navyPanelGrad)" />

                                <!-- Guilloche Overlay Inside Left Panel -->
                                <g clip-path="url(#frontNavyClip)">
                                    <rect x="0" y="0" width="300" height="392" fill="url(#guillochePattern)" />
                                    <!-- Large Concentric Guilloche Rosette Behind Photo & Signature -->
                                    <g transform="translate(110, 290)" fill="none" stroke="#4f94e8" stroke-width="0.6" opacity="0.32">
                                        <ellipse rx="115" ry="42" transform="rotate(0)" />
                                        <ellipse rx="115" ry="42" transform="rotate(20)" />
                                        <ellipse rx="115" ry="42" transform="rotate(40)" />
                                        <ellipse rx="115" ry="42" transform="rotate(60)" />
                                        <ellipse rx="115" ry="42" transform="rotate(80)" />
                                        <ellipse rx="115" ry="42" transform="rotate(100)" />
                                        <ellipse rx="115" ry="42" transform="rotate(120)" />
                                        <ellipse rx="115" ry="42" transform="rotate(140)" />
                                        <ellipse rx="115" ry="42" transform="rotate(160)" />
                                    </g>
                                    <g transform="translate(110, 95)" fill="none" stroke="#4f94e8" stroke-width="0.6" opacity="0.28">
                                        <ellipse rx="110" ry="38" transform="rotate(15)" />
                                        <ellipse rx="110" ry="38" transform="rotate(45)" />
                                        <ellipse rx="110" ry="38" transform="rotate(75)" />
                                        <ellipse rx="110" ry="38" transform="rotate(105)" />
                                        <ellipse rx="110" ry="38" transform="rotate(135)" />
                                        <ellipse rx="110" ry="38" transform="rotate(165)" />
                                    </g>
                                </g>

                                <!-- Horizontal Blue Divider Line Under Header -->
                                <line x1="275" y1="123" x2="548" y2="123" stroke="#3c628c" stroke-width="2.6" />
                            </svg>

                            <!-- Center Faint University Logo Watermark -->
                            <img
                                src="data:image/png;base64,"
                                alt="شعار مائي"
                                class="logo-img-el absolute pointer-events-none"
                                style="width: 192px; height: 192px; right: 92px; top: 108px; opacity: 0.11; filter: grayscale(15%);" />

                            <!-- Top Right Header: University Logo & Name -->
                            <div class="absolute top-[18px] right-[18px] left-[220px] h-[92px] flex items-center justify-start gap-3 z-10">
                                <img
                                    src="data:image/png;base64,"
                                    alt="شعار جامعة العلوم الصحية"
                                    class="logo-img-el w-[86px] h-[86px] rounded-full object-contain shrink-0 drop-shadow-sm" />
                                <h2 id="frontUniName" class="text-[21px] font-extrabold tracking-tight leading-snug" style="color: #21405c;">
                                    جامعة العلوم الصحية
                                </h2>
                            </div>

                            <!-- Left Panel: Employee Portrait Photo -->
                            <div class="photo-frame group">
                                <img
                                    id="employeePhotoImg"
                                    src="data:image/png;base64,"
                                    alt="صورة الموظف"
                                    class="w-full h-full object-cover object-top" />
