                    <label for="inputBackRule3" class="block text-xs font-bold text-slate-300 mb-1">البند الثالث:</label>
                    <textarea id="inputBackRule3" rows="2" class="w-full px-3 py-2 rounded-xl bg-slate-800 border border-slate-700 text-sm text-white focus:outline-none focus:border-blue-500">إذا عثرت على هذه البطاقة يرجى تسليمها إلى إدارة الجامعة
أو الاتصال بالرقم: ٠١٢٣٤٥٦٧٨٩</textarea>
                </div>
            </div>

            <!-- Footer Reset Button -->
            <div class="mt-auto p-4 border-t border-slate-800 bg-slate-900/90 flex items-center justify-between gap-2">
                <button id="btnResetAll" type="button" class="w-full py-2 px-4 rounded-xl bg-slate-800 hover:bg-slate-700 text-xs font-bold text-slate-300 hover:text-white border border-slate-700 transition">
                    ↺ استعادة الإعدادات والبيانات الافتراضية
                </button>
            </div>

        </aside>

    </main>

    <!-- Toast Notification -->
    <div id="toastBanner" class="no-print fixed bottom-5 left-5 z-50 hidden bg-slate-900/95 border border-emerald-500/50 text-white px-4 py-2.5 rounded-xl shadow-2xl text-xs font-bold flex items-center gap-2">
        <span class="text-emerald-400 text-base">✓</span>
        <span id="toastText">تم تحديث البطاقة بنجاح</span>
    </div>

    <!-- ===== Modal نظام الطباعة المتعدد ===== -->
    <div id="printModal" role="dialog" aria-modal="true" aria-labelledby="printModalTitle">
        <div id="printModalInner" dir="rtl">

            <!-- رأس المودال -->
            <div class="flex items-center justify-between mb-5">
                <div class="flex items-center gap-3">
                    <div class="w-10 h-10 rounded-xl bg-blue-600/20 border border-blue-500/40 flex items-center justify-center text-xl">🖨️</div>
                    <div>
                        <h2 id="printModalTitle" class="text-lg font-bold text-white">طباعة البطاقات على ورقة A4</h2>
                        <p class="text-xs text-slate-400">الورقة أفقية • وجه أمامي + خلفي في نفس الصف</p>
                    </div>
                </div>
                <button id="btnClosePrintModal" type="button" class="w-9 h-9 rounded-xl bg-slate-700 hover:bg-slate-600 text-slate-300 hover:text-white flex items-center justify-center text-lg transition">✕</button>
            </div>

            <!-- اختيار عدد البطاقات -->
            <div class="mb-5">
                <p class="text-xs font-bold text-slate-300 mb-2">📌 عدد البطاقات للطباعة:</p>
                <div class="flex gap-2 flex-wrap">
                    <button type="button" class="print-card-count-btn active" data-count="1">1 بطاقة</button>
                    <button type="button" class="print-card-count-btn" data-count="2">2 بطاقة</button>
                    <button type="button" class="print-card-count-btn" data-count="3">3 بطاقات</button>
                    <button type="button" class="print-card-count-btn" data-count="4">4 بطاقات</button>
                </div>
            </div>

            <!-- المحتوى الرئيسي: بيانات البطاقات + معاينة A4 -->
            <div class="flex gap-5 flex-wrap">

                <!-- بيانات البطاقات -->
                <div id="printCardsDataContainer" class="flex-1 min-w-[280px] space-y-0 overflow-y-auto" style="max-height: 420px;">
                    <!-- تُولَّد ديناميكياً بالجافاسكريبت -->
                </div>

                <!-- معاينة A4 -->
                <div class="flex flex-col items-center gap-3">
                    <p class="text-xs font-bold text-slate-400">معاينة توزيع البطاقات على A4:</p>
                    <div class="print-a4-preview" id="a4Preview">
                        <div class="print-a4-slot" id="a4slot0">أمامي 1</div>
                        <div class="print-a4-slot" id="a4slot1">خلفي 1</div>
                        <div class="print-a4-slot" id="a4slot2">أمامي 2</div>
                        <div class="print-a4-slot" id="a4slot3">خلفي 2</div>
                    </div>
                    <div class="text-center">
                        <p class="text-xs text-slate-500 font-mono">A4 أفقي (297×210mm)</p>
                        <p class="text-xs text-slate-500">البطاقة: ~128×91mm</p>
                    </div>

                    <!-- خيار: طباعة بالبيانات الحالية -->
                    <button id="btnPrintCurrentData" type="button" class="mt-2 w-full px-4 py-2 rounded-xl bg-slate-700 hover:bg-slate-600 border border-slate-600 text-xs font-semibold text-slate-200 transition text-center">
                        ⚡ طباعة بالبيانات الحالية (بطاقة واحدة)
                    </button>
                </div>
            </div>

            <!-- أزرار الإجراء -->
            <div class="mt-5 pt-4 border-t border-slate-700 flex gap-3 justify-end flex-wrap">
                <button id="btnCancelPrint" type="button" class="px-5 py-2.5 rounded-xl bg-slate-700 hover:bg-slate-600 text-sm font-semibold text-slate-200 transition">
                    إلغاء
                </button>
                <button id="btnExecutePrint" type="button" class="px-6 py-2.5 rounded-xl bg-blue-600 hover:bg-blue-500 text-sm font-bold text-white shadow-lg shadow-blue-900/40 flex items-center gap-2 transition">
                    <span>🖨️</span>
                    <span>طباعة الآن</span>
                </button>
            </div>
        </div>
    </div>

    <!-- ===== طبقة الطباعة الفعلية (مخفية، تظهر عند الطباعة فقط) ===== -->
    <div id="printOverlay">
        <div id="printContent"></div>
    </div>

    <script>
        // Embedded Asset Data URIs (populated automatically during build)
        const SIG_WHITE_SRC = "data:image/png;base64,";
        const SIG_DARK_SRC = "data:image/png;base64,";
        const DEFAULT_PORTRAIT_SRC = "data:image/png;base64,";
        const DEFAULT_LOGO_SRC = "data:image/png;base64,";

        // Application State
        const state = {
            viewMode: 'both', // 'both' | 'flip' | 'front' | 'back'
            isFlipped: false,
            editorOpen: true,
            zoom: 100,
            sigStyle: 'silver', // 'silver' | 'gold' | 'cyan' | 'dark' | 'custom'
            customSigSrc: null,
            sigScale: 108,
            sigX: 0,
            sigY: 2,
            sigRot: 0,
            sigOpacity: 96
        };

        // Helper: Toast Notification
        let toastTimer = null;

        function showToast(msg) {
            const banner = document.getElementById('toastBanner');
            const text = document.getElementById('toastText');
            if (!banner || !text) return;
            text.textContent = msg;
            banner.classList.remove('hidden');
            if (toastTimer) clearTimeout(toastTimer);
            toastTimer = setTimeout(() => {
                banner.classList.add('hidden');
            }, 2600);
        }

        // Update Signature Transform & Style
        function updateSignatureRender() {
            const sigImg = document.getElementById('cardSignatureImg');
            const previewSig = document.getElementById('previewBoxSigImg');
            if (!sigImg) return;

            // Choose source based on style
            if (state.customSigSrc) {
                sigImg.src = state.customSigSrc;
                if (previewSig) previewSig.src = state.customSigSrc;
            } else if (state.sigStyle === 'dark') {
                sigImg.src = SIG_DARK_SRC;
                if (previewSig) previewSig.src = SIG_DARK_SRC;
            } else {
                sigImg.src = SIG_WHITE_SRC;
                if (previewSig) previewSig.src = SIG_WHITE_SRC;
            }

            // Apply filter class
            sigImg.classList.remove('sig-tint-silver', 'sig-tint-gold', 'sig-tint-cyan', 'sig-tint-dark');
            if (state.sigStyle === 'gold') {
                sigImg.classList.add('sig-tint-gold');
            } else if (state.sigStyle === 'cyan') {
                sigImg.classList.add('sig-tint-cyan');
            } else if (state.sigStyle === 'dark') {
                sigImg.classList.add('sig-tint-dark');
            } else {
                sigImg.classList.add('sig-tint-silver');
            }

            const scaleFactor = (state.sigScale / 100).toFixed(2);
            sigImg.style.transform = `translate(${state.sigX}px, ${state.sigY}px) scale(${scaleFactor}) rotate(${state.sigRot}deg)`;
            sigImg.style.opacity = (state.sigOpacity / 100).toFixed(2);

            // Update labels
            document.getElementById('sigScaleVal').textContent = `${state.sigScale}%`;
            document.getElementById('sigXVal').textContent = `${state.sigX}px`;
            document.getElementById('sigYVal').textContent = `${state.sigY}px`;
            document.getElementById('sigRotVal').textContent = `${state.sigRot}°`;
            document.getElementById('sigOpacityVal').textContent = `${state.sigOpacity}%`;
        }

        // View Mode Switching ('both', 'flip', 'front', 'back')
        function setViewMode(mode) {
            state.viewMode = mode;
            const frontWrap = document.getElementById('frontCardWrapper');
            const backWrap = document.getElementById('backCardWrapper');
            const layoutBox = document.getElementById('cardsLayoutBox');
            const flipHint = document.getElementById('flipHintBar');

            // Reset classes
            frontWrap.classList.remove('hidden', 'flip-face');
            backWrap.classList.remove('hidden', 'flip-face', 'flip-back');
            layoutBox.classList.remove('flip-container', 'is-flipped');
            layoutBox.parentElement.classList.remove('perspective-stage');
            flipHint.classList.add('hidden');

            if (mode === 'both') {
                layoutBox.className = 'flex flex-col xl:flex-row items-center justify-center gap-8';
            } else if (mode === 'front') {
                layoutBox.className = 'flex items-center justify-center';
                backWrap.classList.add('hidden');
            } else if (mode === 'back') {
                layoutBox.className = 'flex items-center justify-center';
                frontWrap.classList.add('hidden');
            } else if (mode === 'flip') {
                layoutBox.parentElement.classList.add('perspective-stage');
                layoutBox.className = 'flip-container';
                if (state.isFlipped) layoutBox.classList.add('is-flipped');
                frontWrap.classList.add('flip-face');
                backWrap.classList.add('flip-face', 'flip-back');
                flipHint.classList.remove('hidden');
            }

            // Highlight active button
            const map = {
                both: 'btnViewBoth',
                flip: 'btnViewFlip',
                front: 'btnViewFront',
                back: 'btnViewBack'
            };
            Object.entries(map).forEach(([k, id]) => {
                const btn = document.getElementById(id);
                if (!btn) return;
                if (k === mode) {
                    btn.className = 'px-3 py-1.5 rounded-lg font-semibold bg-blue-600 text-white shadow transition';
                } else {
                    btn.className = 'px-3 py-1.5 rounded-lg font-semibold text-slate-300 hover:text-white transition';
                }
            });
        }

        // Responsive Auto-Scale Calculation
        function applyZoomScale() {
            const container = document.getElementById('cardsScaleContainer');
            const stage = document.getElementById('previewStage');
            if (!container || !stage) return;

            const stageWidth = stage.clientWidth - 32;
            let baseScale = 1;
            if (stageWidth < 580) {
                baseScale = Math.max(0.52, stageWidth / 565);
            }
            const finalScale = baseScale * (state.zoom / 100);
            container.style.transform = `scale(${finalScale.toFixed(3)})`;
            document.getElementById('zoomValueLabel').textContent = `${state.zoom}%`;
        }

        // Export Both Cards as High-Resolution PNG via HTML5 Canvas
        async function exportHighResPng() {
            showToast('جاري تجهيز صورة البطاقة بدقة عالية...');
            const canvas = document.createElement('canvas');
            const scale = 2;
            const cardW = 548;
            const cardH = 392;
            const pad = 36;
            const gap = 36;
            canvas.width = (cardW * 2 + pad * 2 + gap) * scale;
            canvas.height = (cardH + pad * 2) * scale;
            const ctx = canvas.getContext('2d');
            ctx.scale(scale, scale);

            // Draw Stone Background
            const bgGrad = ctx.createLinearGradient(0, 0, cardW * 2 + pad * 2 + gap, cardH + pad * 2);
            bgGrad.addColorStop(0, '#d5d3ce');
            bgGrad.addColorStop(0.5, '#c4c2bc');
            bgGrad.addColorStop(1, '#b2b0aa');
            ctx.fillStyle = bgGrad;
            ctx.fillRect(0, 0, cardW * 2 + pad * 2 + gap, cardH + pad * 2);

            // Helper to load image
            const loadImg = (src) => new Promise((resolve) => {
                const img = new Image();
                img.crossOrigin = 'anonymous';
                img.onload = () => resolve(img);
                img.onerror = () => resolve(null);
                img.src = src;
            });

            const portraitImg = await loadImg(document.getElementById('employeePhotoImg').src);
            const logoImg = await loadImg(document.querySelector('.logo-img-el').src);
            const sigImg = await loadImg(document.getElementById('cardSignatureImg').src);

            // Helper: Rounded Rect Path
            function roundRectPath(c, x, y, w, h, r) {
                c.beginPath();
                c.moveTo(x + r, y);
                c.lineTo(x + w - r, y);
                c.quadraticCurveTo(x + w, y, x + w, y + r);
                c.lineTo(x + w, y + h - r);
                c.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
                c.lineTo(x + r, y + h);
                c.quadraticCurveTo(x, y + h, x, y + h - r);
                c.lineTo(x, y + r);
                c.quadraticCurveTo(x, y, x + r, y);
                c.closePath();
            }

            // 1. Draw Front Card at (pad, pad)
            ctx.save();
            ctx.translate(pad, pad);
            ctx.shadowColor = 'rgba(0,0,0,0.28)';
            ctx.shadowBlur = 22;
            ctx.shadowOffsetX = -8;
            ctx.shadowOffsetY = 14;
            roundRectPath(ctx, 0, 0, cardW, cardH, 20);
            ctx.fillStyle = '#ecebe6';
            ctx.fill();
            ctx.shadowColor = 'transparent';
            ctx.clip();

            // Rim Blue Curve
            ctx.fillStyle = 'rgba(95, 130, 172, 0.7)';
            ctx.beginPath();
            ctx.moveTo(0, 0);
            ctx.lineTo(222, 0);
            ctx.bezierCurveTo(244, 40, 255, 96, 312, 123);
            ctx.bezierCurveTo(248, 134, 217, 172, 224, 232);
            ctx.bezierCurveTo(231, 290, 238, 342, 200, 392);
            ctx.lineTo(0, 392);
            ctx.closePath();
            ctx.fill();

            // Navy Panel Curve
            const navyGrad = ctx.createLinearGradient(0, 0, 260, 392);
            navyGrad.addColorStop(0, '#153268');
            navyGrad.addColorStop(0.5, '#1b3b75');
            navyGrad.addColorStop(1, '#102754');
            ctx.fillStyle = navyGrad;
            ctx.beginPath();
            ctx.moveTo(0, 0);
            ctx.lineTo(210, 0);
            ctx.bezierCurveTo(232, 38, 242, 96, 292, 123);
            ctx.bezierCurveTo(235, 134, 205, 172, 212, 232);
            ctx.bezierCurveTo(219, 290, 226, 342, 188, 392);
            ctx.lineTo(0, 392);
            ctx.closePath();
            ctx.fill();

            // Divider Line
            ctx.strokeStyle = '#3c628c';
            ctx.lineWidth = 2.6;
            ctx.beginPath();
            ctx.moveTo(275, 123);
            ctx.lineTo(548, 123);
            ctx.stroke();

            // Watermark Logo
            if (logoImg) {
                ctx.save();
                ctx.globalAlpha = 0.11;
                ctx.drawImage(logoImg, cardW - 92 - 192, 108, 192, 192);
                ctx.restore();
                // Top Right Logo
                ctx.drawImage(logoImg, cardW - 18 - 86, 18, 86, 86);
            }

            // Header Text
            ctx.direction = 'rtl';
            ctx.textAlign = 'right';
            ctx.fillStyle = '#21405c';
            ctx.font = '800 21px Cairo, sans-serif';
            ctx.fillText(document.getElementById('frontUniName').textContent.trim(), cardW - 116, 68);

            // Portrait Photo
            if (portraitImg) {
                ctx.save();
                roundRectPath(ctx, 38, 56, 147, 206, 16);
                ctx.clip();
                ctx.drawImage(portraitImg, 38, 56, 147, 206);
                ctx.restore();
                ctx.strokeStyle = '#d4d7dd';
                ctx.lineWidth = 3.5;
                roundRectPath(ctx, 38, 56, 147, 206, 16);
                ctx.stroke();
            }

            // Signature on Front Card
            if (sigImg) {
                ctx.save();
                ctx.globalAlpha = state.sigOpacity / 100;
                const cx = 110 + Number(state.sigX);
                const cy = 312 + Number(state.sigY);
                ctx.translate(cx, cy);
                ctx.rotate((state.sigRot * Math.PI) / 180);
                const s = state.sigScale / 100;
                ctx.drawImage(sigImg, -75 * s, -42 * s, 150 * s, 84 * s);
                ctx.restore();
            }

            // Signature Caption
            ctx.textAlign = 'center';
            ctx.fillStyle = '#d1dceb';
            ctx.font = '700 12.5px Cairo, sans-serif';
            ctx.fillText(document.getElementById('frontSigCaption').textContent.trim(), 110, 374);

            // Employee Info
            ctx.textAlign = 'right';
            ctx.fillStyle = '#13181f';
            ctx.font = '900 30px Cairo, sans-serif';
            ctx.fillText(document.getElementById('frontEmpName').textContent.trim(), cardW - 26, 174);

            ctx.fillStyle = '#1c232d';
            ctx.font = '700 16.5px Cairo, sans-serif';
            ctx.fillText('الإدارة: ' + document.getElementById('frontEmpDept').textContent.trim(), cardW - 26, 212);
            ctx.fillText('الوظيفة: ' + document.getElementById('frontEmpRole').textContent.trim(), cardW - 26, 242);
            ctx.fillText('رقم الهاتف: ' + document.getElementById('frontEmpPhone').textContent.trim(), cardW - 26, 272);
            ctx.fillText('تاريخ الإصدار: ' + document.getElementById('frontEmpDate').textContent.trim(), cardW - 26, 302);

            // Barcode
            ctx.fillStyle = '#1c223d';
            const bars = [0, 4.5, 8, 13, 16.5, 20, 25, 28.5, 33, 36.5, 42, 45.5, 50, 53.5, 58.5, 62, 67, 70.5, 75, 78.5, 84, 87.5, 92, 95.5, 100.5, 104, 109, 112.5, 117, 120.5, 125.5];
            const widths = [2.5, 1.2, 3, 1.5, 1.2, 2.8, 1.2, 2.2, 1.2, 3.2, 1.5, 2.5, 1.2, 2.8, 1.5, 3, 1.2, 2.4, 1.5, 3.2, 1.2, 2.5, 1.5, 2.8, 1.2, 3, 1.5, 2.5, 1.2, 3, 2];
            const bx = cardW - 36 - 128;
            const by = cardH - 18 - 24;
            bars.forEach((xOff, idx) => {
                ctx.fillRect(bx + xOff, by, widths[idx], 24);
            });
            ctx.restore();

            // 2. Draw Back Card at (pad + cardW + gap, pad)
            ctx.save();
            ctx.translate(pad + cardW + gap, pad);
            ctx.shadowColor = 'rgba(0,0,0,0.28)';
            ctx.shadowBlur = 22;
            ctx.shadowOffsetX = -8;
            ctx.shadowOffsetY = 14;
            roundRectPath(ctx, 0, 0, cardW, cardH, 20);
            ctx.fillStyle = '#ecebe6';
            ctx.fill();
            ctx.shadowColor = 'transparent';
            ctx.clip();

            // Back Top-Left Rim & Navy Panel
            ctx.fillStyle = 'rgba(95, 130, 172, 0.7)';
            ctx.beginPath();
            ctx.moveTo(0, 0);
            ctx.lineTo(198, 0);
            ctx.bezierCurveTo(224, 42, 238, 95, 296, 123);
            ctx.lineTo(0, 123);
            ctx.closePath();
            ctx.fill();

            ctx.fillStyle = navyGrad;
            ctx.beginPath();
            ctx.moveTo(0, 0);
            ctx.lineTo(186, 0);
            ctx.bezierCurveTo(212, 42, 225, 95, 276, 123);
            ctx.lineTo(0, 123);
            ctx.closePath();
            ctx.fill();

            // Full-Width Divider Line
            ctx.strokeStyle = '#3c628c';
            ctx.lineWidth = 2.6;
            ctx.beginPath();
            ctx.moveTo(0, 123);
            ctx.lineTo(548, 123);
            ctx.stroke();

            if (logoImg) {
                ctx.save();
                ctx.globalAlpha = 0.11;
                ctx.drawImage(logoImg, 38, 118, 196, 196);
                ctx.restore();
                ctx.drawImage(logoImg, cardW - 26 - 86, 18, 86, 86);
            }

            ctx.direction = 'rtl';
            ctx.textAlign = 'right';
            ctx.fillStyle = '#21405c';
            ctx.font = '800 21px Cairo, sans-serif';
            ctx.fillText(document.getElementById('backUniName').textContent.trim(), cardW - 124, 68);

            ctx.fillStyle = '#13181f';
            ctx.font = '900 30px Cairo, sans-serif';
            ctx.fillText(document.getElementById('backHeading').textContent.trim(), cardW - 30, 182);

            ctx.fillStyle = '#1b222c';
            ctx.font = '700 16.5px Cairo, sans-serif';
            ctx.fillText('• ' + document.getElementById('backRule1').textContent.trim(), cardW - 30, 225);
            ctx.fillText('• ' + document.getElementById('backRule2').textContent.trim(), cardW - 30, 260);

            const rule3Lines = document.getElementById('backRule3').textContent.split('\n');
            if (rule3Lines[0]) {
                ctx.fillText('• ' + rule3Lines[0].trim(), cardW - 30, 295);
            }
            if (rule3Lines[1]) {
                ctx.fillText(rule3Lines[1].trim(), cardW - 44, 323);
            }
            ctx.restore();

            // Trigger Download
            const link = document.createElement('a');
            link.download = 'university_id_card_updated.png';
            link.href = canvas.toDataURL('image/png');
            link.click();
            showToast('تم تحميل صورة البطاقة عالية الدقة (PNG) بنجاح!');
        }

        // Wire Up All Interactive Controls on DOMContentLoaded
        window.addEventListener('DOMContentLoaded', () => {
            // View Mode Buttons
            document.getElementById('btnViewBoth').addEventListener('click', () => setViewMode('both'));
            document.getElementById('btnViewFlip').addEventListener('click', () => setViewMode('flip'));
            document.getElementById('btnViewFront').addEventListener('click', () => setViewMode('front'));
            document.getElementById('btnViewBack').addEventListener('click', () => setViewMode('back'));

            // 3D Flip Trigger
            const toggleFlip = () => {
                if (state.viewMode !== 'flip') return;
                state.isFlipped = !state.isFlipped;
                document.getElementById('cardsLayoutBox').classList.toggle('is-flipped', state.isFlipped);
            };
            document.getElementById('btnFlipAction').addEventListener('click', toggleFlip);
            document.getElementById('cardsLayoutBox').addEventListener('click', toggleFlip);

            // Toggle Editor Sidebar
            document.getElementById('btnToggleEditor').addEventListener('click', () => {
                state.editorOpen = !state.editorOpen;
                const panel = document.getElementById('editorPanel');
                const label = document.getElementById('editorToggleLabel');
                panel.classList.toggle('hidden', !state.editorOpen);
                label.textContent = state.editorOpen ? 'إخفاء لوحة التحكم' : 'إظهار لوحة التحكم';
                setTimeout(applyZoomScale, 50);
            });

            // Print & Export PNG
            document.getElementById('btnPrintCard').addEventListener('click', () => window.print());
            document.getElementById('btnDownloadPng').addEventListener('click', exportHighResPng);

            // Stage Backdrop Switcher
            document.querySelectorAll('.bg-preset-btn').forEach((btn) => {
                btn.addEventListener('click', () => {
                    const bg = btn.getAttribute('data-bg');
                    const stage = document.getElementById('previewStage');
                    stage.classList.remove('stone-backdrop', 'dark-backdrop', 'light-backdrop');
                    stage.classList.add(`${bg}-backdrop`);
                    document.querySelectorAll('.bg-preset-btn').forEach((b) => {
                        b.className = 'bg-preset-btn px-2.5 py-1 rounded-full bg-slate-800 text-slate-300 hover:text-white transition';
                    });
                    btn.className = 'bg-preset-btn px-2.5 py-1 rounded-full bg-blue-600 text-white font-semibold transition';
                });
            });

            // Zoom Slider
            document.getElementById('zoomRange').addEventListener('input', (e) => {
                state.zoom = Number(e.target.value);
                applyZoomScale();
            });
            window.addEventListener('resize', applyZoomScale);

            // Editor Tab Switching
            document.querySelectorAll('.editor-tab-btn').forEach((btn) => {
                btn.addEventListener('click', () => {
                    const targetId = btn.getAttribute('data-tab');
                    document.querySelectorAll('.editor-tab-pane').forEach((pane) => {
                        pane.classList.toggle('hidden', pane.id !== targetId);
                    });
                    document.querySelectorAll('.editor-tab-btn').forEach((b) => {
                        if (b === btn) {
                            b.className = 'editor-tab-btn py-2 rounded-lg bg-blue-600 text-white shadow transition';
                        } else {
                            b.className = 'editor-tab-btn py-2 rounded-lg text-slate-300 hover:text-white transition';
                        }
                    });
                });
            });

            // Signature Style Buttons
            document.querySelectorAll('.sig-style-btn').forEach((btn) => {
                btn.addEventListener('click', () => {
                    state.sigStyle = btn.getAttribute('data-sig-style');
                    document.querySelectorAll('.sig-style-btn').forEach((b) => {
                        if (b === btn) {
                            b.className = 'sig-style-btn px-3 py-2 rounded-xl border border-blue-500 bg-blue-600/20 text-white flex items-center gap-2 transition';
                        } else {
                            b.className = 'sig-style-btn px-3 py-2 rounded-xl border border-slate-700 bg-slate-800 text-slate-300 hover:text-white flex items-center gap-2 transition';
                        }
                    });
                    updateSignatureRender();
                });
            });

            // Signature Sliders
            document.getElementById('sigScaleInput').addEventListener('input', (e) => {
                state.sigScale = Number(e.target.value);
                updateSignatureRender();
            });
            document.getElementById('sigXInput').addEventListener('input', (e) => {
                state.sigX = Number(e.target.value);
                updateSignatureRender();
            });
            document.getElementById('sigYInput').addEventListener('input', (e) => {
                state.sigY = Number(e.target.value);
                updateSignatureRender();
            });
            document.getElementById('sigRotInput').addEventListener('input', (e) => {
                state.sigRot = Number(e.target.value);
                updateSignatureRender();
            });
            document.getElementById('sigOpacityInput').addEventListener('input', (e) => {
                state.sigOpacity = Number(e.target.value);
                updateSignatureRender();
            });

            // Live Text Bindings
            const bindInput = (inputId, targetIds) => {
                const inp = document.getElementById(inputId);
                if (!inp) return;
                inp.addEventListener('input', () => {
                    targetIds.forEach((tid) => {
                        const el = document.getElementById(tid);
                        if (el) el.textContent = inp.value;
                    });
                });
            };

            bindInput('inputSigCaption', ['frontSigCaption']);
            bindInput('inputUniName', ['frontUniName', 'backUniName']);
            bindInput('inputEmpName', ['frontEmpName']);
            bindInput('inputEmpDept', ['frontEmpDept']);
            bindInput('inputEmpRole', ['frontEmpRole']);
            bindInput('inputEmpPhone', ['frontEmpPhone']);
            bindInput('inputEmpDate', ['frontEmpDate']);
            bindInput('inputBackHeading', ['backHeading']);
            bindInput('inputBackRule1', ['backRule1']);
            bindInput('inputBackRule2', ['backRule2']);
            bindInput('inputBackRule3', ['backRule3']);

            // File Uploads (Signature, Portrait Photo, University Logo)
            document.getElementById('uploadSigFile').addEventListener('change', (e) => {
                const file = e.target.files && e.target.files[0];
                if (!file) return;
                const reader = new FileReader();
                reader.onload = (ev) => {
                    state.customSigSrc = ev.target.result;
                    updateSignatureRender();
                    showToast('تم رفع التوقيع الجديد وتطبيقه على البطاقة');
                };
                reader.readAsDataURL(file);
            });

            document.getElementById('uploadPhotoFile').addEventListener('change', (e) => {
                const file = e.target.files && e.target.files[0];
                if (!file) return;
                const reader = new FileReader();
                reader.onload = (ev) => {
                    document.getElementById('employeePhotoImg').src = ev.target.result;
                    showToast('تم تحديث الصورة الشخصية بنجاح');
                };
                reader.readAsDataURL(file);
            });

            document.getElementById('uploadLogoFile').addEventListener('change', (e) => {
                const file = e.target.files && e.target.files[0];
                if (!file) return;
                const reader = new FileReader();
                reader.onload = (ev) => {
                    document.querySelectorAll('.logo-img-el').forEach((img) => {
                        img.src = ev.target.result;
                    });
                    showToast('تم تحديث شعار الجامعة بنجاح');
                };
                reader.readAsDataURL(file);
            });

            // Reset Button
            document.getElementById('btnResetAll').addEventListener('click', () => {
                state.sigStyle = 'silver';
                state.customSigSrc = null;
                state.sigScale = 108;
                state.sigX = 0;
                state.sigY = 2;
                state.sigRot = 0;
                state.sigOpacity = 96;
                state.zoom = 100;

                document.getElementById('sigScaleInput').value = 108;
                document.getElementById('sigXInput').value = 0;
                document.getElementById('sigYInput').value = 2;
                document.getElementById('sigRotInput').value = 0;
                document.getElementById('sigOpacityInput').value = 96;
                document.getElementById('zoomRange').value = 100;

                const defaults = {
                    inputSigCaption: 'توقيع المدير الإداري',
                    inputUniName: 'جامعة العلوم الصحية',
                    inputEmpName: 'أحمد محمد علي',
                    inputEmpDept: 'إدارة تقنية المعلومات',
                    inputEmpRole: 'مبرمج أنظمة',
                    inputEmpPhone: '٠١٢٣٤٥٦٧٨٩',
                    inputEmpDate: '٢٠٢٦',
                    inputBackHeading: 'إرشادات هامة',
                    inputBackRule1: 'يجب إبلاغ الجامعة فوراً في حالة فقدان البطاقة',
                    inputBackRule2: 'يُسمح لحامل البطاقة بدخول كافة المرافق الحكومية والمستشفيات',
                    inputBackRule3: 'إذا عثرت على هذه البطاقة يرجى تسليمها إلى إدارة الجامعة\nأو الاتصال بالرقم: ٠١٢٣٤٥٦٧٨٩'
                };
                Object.entries(defaults).forEach(([id, val]) => {
                    const el = document.getElementById(id);
                    if (el) {
                        el.value = val;
                        el.dispatchEvent(new Event('input'));
                    }
                });

                document.getElementById('employeePhotoImg').src = DEFAULT_PORTRAIT_SRC;
                document.querySelectorAll('.logo-img-el').forEach((img) => {
                    img.src = DEFAULT_LOGO_SRC;
                });

                updateSignatureRender();
                applyZoomScale();
                showToast('تمت استعادة الإعدادات الافتراضية');
            });

            // Initial render
            updateSignatureRender();
            applyZoomScale();
        });
    </script>
</body>

</html>